using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
using SteamVrTranslator;

internal static class WindowCaptureTests
{
    private sealed class FixtureForm : Form
    {
        protected override bool ShowWithoutActivation => true;
        protected override CreateParams CreateParams
        {
            get { var cp = base.CreateParams; cp.ExStyle &= ~0x80; return cp; }
        }
    }
    [DllImport("user32")] private static extern nint WindowFromPoint(Point point);

    // Both windows and every asserted pixel are generated by this fixture. No screenshots are saved.
    internal static void RunFixture(string nonce)
    {
        if (!Guid.TryParseExact(nonce, "N", out _)) throw new ArgumentException(nameof(nonce));
        var thread = new Thread(() =>
        {
            Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
            var work = Screen.PrimaryScreen!.WorkingArea;
            var location = new Point(work.Right - 235, work.Bottom - 170);
            using var target = new FixtureForm { Text = nonce, FormBorderStyle = FormBorderStyle.None,
                StartPosition = FormStartPosition.Manual, Bounds = new Rectangle(location, new Size(210,140)), BackColor = Color.Lime };
            using var cover = new FixtureForm { Text = nonce + "-cover", FormBorderStyle = FormBorderStyle.None,
                StartPosition = FormStartPosition.Manual, Bounds = target.Bounds, BackColor = Color.Magenta, TopMost = true };
            target.Shown += async (_, _) =>
            {
                try
                {
                    cover.Show(); target.Refresh(); cover.Refresh();
                    Console.WriteLine(WindowFromPoint(target.PointToScreen(new Point(95,65))) == cover.Handle ? "covered" : "uncovered");
                    while (await Task.Run(Console.ReadLine) is { } command)
                    {
                        if (command == "minimize") target.WindowState = FormWindowState.Minimized;
                        else if (command == "restore") target.WindowState = FormWindowState.Normal;
                        else if (command == "black") { target.BackColor = Color.Black; target.Refresh(); }
                        else break;
                        Console.WriteLine("ok");
                    }
                }
                finally { cover.Close(); target.Close(); }
            };
            Application.Run(target);
        });
        thread.SetApartmentState(ApartmentState.STA);
        thread.Start(); thread.Join();
    }

    internal static async Task RunAsync()
    {
        string nonce = Guid.NewGuid().ToString("N");
        var start = new ProcessStartInfo(Environment.ProcessPath!) { RedirectStandardInput = true, RedirectStandardOutput = true, UseShellExecute = false, CreateNoWindow = true };
        if (Path.GetFileNameWithoutExtension(start.FileName).Equals("dotnet", StringComparison.OrdinalIgnoreCase))
            start.ArgumentList.Add(typeof(WindowCaptureTests).Assembly.Location);
        start.ArgumentList.Add("--synthetic-window-fixture"); start.ArgumentList.Add(nonce);
        using var fixture = Process.Start(start)!;
        async Task<string?> Line() => await fixture.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(12));
        async Task Command(string command)
        {
            await fixture.StandardInput.WriteLineAsync(command);
            if (await Line() != "ok") throw new Exception("Synthetic capture fixture failed");
        }
        try
        {
            if (await Line() != "covered") throw new Exception("The synthetic magenta window must physically cover the green target");
            var options = WindowCaptureService.ListWindows();
            var choice = options.Single(o => o.Title == nonce);
            if (WindowCaptureService.ListWindows().Single(o => o.Title == nonce).Id != choice.Id) throw new Exception("Window ID changed on refresh");
            var config = new AppSettings { DesktopCaptureSource = "Window", DesktopWindowId = choice.Id };
            string json = JsonSerializer.Serialize(config);
            if (!json.Contains("DesktopCaptureSource") || json.Contains(choice.Id) || json.Contains(nonce)) throw new Exception("Window identity leaked to persisted settings");
            Size size;
            using (var actual = await WindowCaptureService.CaptureAsync(config,CancellationToken.None).WaitAsync(TimeSpan.FromSeconds(12)))
            {
                size = actual.Size;
                var pixel = actual.GetPixel(actual.Width/2,actual.Height/2);
                if (pixel.G < 220 || pixel.B > 30 || pixel.R > 30) throw new Exception("Selected occluded green pixels were not captured");
            }
            config.CropWidth = .5f;
            using (var half = await WindowCaptureService.CaptureAsync(config, CancellationToken.None))
                if (half.Width != (size.Width+1)/2 || half.Height != size.Height) throw new Exception("Crop did not use the captured window's physical pixels");
            await Command("minimize");
            await ExpectFailure(config, "最小化");
            await Command("restore"); await Command("black");
            await ExpectFailure(config, "全黑");
            await fixture.StandardInput.WriteLineAsync("close"); await fixture.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(5));
            await ExpectFailure(config, "已关闭");
            Console.WriteLine($"PASS target-window capture: verified occlusion, {size.Width}x{size.Height} native pixels, crop, minimized/blank/closed failures and session-only identity");
        }
        finally
        {
            if (!fixture.HasExited) { fixture.Kill(entireProcessTree:true); await fixture.WaitForExitAsync(); }
        }
    }

    private static async Task ExpectFailure(AppSettings settings, string text)
    {
        try { using var unexpected = await WindowCaptureService.CaptureAsync(settings,CancellationToken.None); }
        catch (InvalidOperationException ex) when (ex.Message.Contains(text)) { return; }
        throw new Exception("Unavailable test window unexpectedly yielded pixels");
    }
}
